def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    # Defensive access for possible missing keys
    grid_width = observation.get("grid_width", 0)
    grid_height = observation.get("grid_height", 0)
    resources = observation.get("resources") or []
    resources = [res for res in resources if isinstance(res, (list, tuple)) and len(res) >= 2]
    unclaimed = observation.get("unclaimed_cells") or []
    unclaimed = [cell for cell in unclaimed if isinstance(cell, (list, tuple)) and len(cell) >= 2]
    opponent_territory = observation.get("opponent_territory") or []
    opponent_territory = [cell for cell in opponent_territory if isinstance(cell, (list, tuple)) and len(cell) >= 2]
    role = observation.get("self_role", "pursuer")

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Pursuit/Evasion logic
    if env == "pursuit_evasion":
        if role == "pursuer":
            dx, dy = move_towards(ox, oy)
            return [dx, dy]
        # Evader: move away from opponent
        away_x = sx
        away_y = sy
        if ox > sx:
            away_x -= 1
        elif ox < sx:
            away_x += 1
        if oy > sy:
            away_y -= 1
        elif oy < sy:
            away_y += 1
        return move_towards(away_x, away_y)

    # Territory Control logic
    if env == "territory_control":
        targets = unclaimed or opponent_territory
        if targets:
            target = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return move_towards(target[0], target[1])
        else:
            # No targets, stay still
            return [0, 0]

    # Resource collection logic
    if resources:
        target = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(target[0], target[1])
    else:
        # No resources, move towards opponent or stay
        return move_towards(ox, oy)

